INSERT INTO EMF_PROCESS_MAPPING (MAPPING_NAME, DATA_COLUMN_NAME, DATA_TABLE_NAME, WHERE_CLAUSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PROCESS_CODE) VALUES ('DON HLA REQUESTED', NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM DONATION_INTERDICTIONS DI, donations dn, units u
 WHERE DI.transaction_id = DN.transaction_id
   AND dn.unit_id = u.unit_id
	 AND DN.UNIT_ID = :P_UNIT_ID
	 AND DI.INTER_CODE :P_OPER_INTER_CODE :P_VALUE_INTER_CODE', 'VDIEMCFG', TO_DATE('2024-02-21 08:23:00', 'YYYY-MM-DD HH24:MI:SS'), 'SBCSYS : P', 'TRALIPL');
INSERT INTO EMF_PROCESS_MAPPING (MAPPING_NAME, DATA_COLUMN_NAME, DATA_TABLE_NAME, WHERE_CLAUSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PROCESS_CODE) VALUES ('DON INTER PRESENT', NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM DUAL
WHERE 1 = ( SELECT DECODE(COUNT(1), 0, 0, 1)
  FROM UNITS U, DONATIONS DN, DONOR_INTERDICTIONS DI
 WHERE U.UNIT_ID = DN.UNIT_ID
   AND DN.UNIT_ID = :P_UNIT_ID
   AND DN.DONOR_ID = DI.DONOR_ID
   AND DI.INTER_CODE :P_OPER_INTER_CODE :P_VALUE_INTER_CODE
   AND DN.COLL_DATE BETWEEN DI.EFF_DATE AND NVL(DI.TERM_DATE, DN.COLL_DATE + 1)
)', 'VDIEMCFG', TO_DATE('2024-01-14 04:22:21', 'YYYY-MM-DD HH24:MI:SS'), 'MANUAL', 'TRALIPL');
