INSERT INTO EMF_PROCESS_MAPPING (MAPPING_NAME, DATA_COLUMN_NAME, DATA_TABLE_NAME, WHERE_CLAUSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PROCESS_CODE) VALUES ('DON HH ANSWER PRESENT', NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM health_history hh, donations dn, units u
 WHERE hh.transaction_id = dn.transaction_id
   AND dn.unit_id = u.unit_id
   AND dn.unit_id = :P_UNIT_ID
   AND hh.question_code :P_OPER_QUESTION_CODE :P_VALUE_QUESTION_CODE
   AND hh.answer_code :P_OPER_ANSWER_CODE :P_VALUE_ANSWER_CODE', 'VDIEMCFG', TO_DATE('2024-01-14 04:22:21', 'YYYY-MM-DD HH24:MI:SS'), 'MANUAL', 'TRALIPL');
INSERT INTO EMF_PROCESS_MAPPING (MAPPING_NAME, DATA_COLUMN_NAME, DATA_TABLE_NAME, WHERE_CLAUSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PROCESS_CODE) VALUES ('INC_DT GT INTER_DT', NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM DUAL
 WHERE
    (SELECT incident_date 
       FROM health_history hh 
      WHERE hh.transaction_id = (SELECT A.transaction_id FROM DONATIONS A WHERE A.unit_id = :P_UNIT_ID)
        AND hh.question_code :P_OPER_QUESTION_CODE :P_VALUE_QUESTION_CODE
        AND hh.answer_code  :P_OPER_ANSWER_CODE :P_VALUE_ANSWER_CODE
        AND ROWNUM = 1
     ) > (SELECT NVL(MAX(di.eff_date), SYSDATE - 100)
            FROM donor_interdictions di
            WHERE di.donor_id = ( SELECT dn.donor_id FROM donations dn WHERE dn.unit_id = :P_UNIT_ID)
                AND trunc(sysdate) BETWEEN di.eff_date AND nvl(di.term_date, sysdate + 10)
                AND di.inter_code :P_OPER_INTER_CODE :P_VALUE_INTER_CODE
        )', 'VDIEMCFG', TO_DATE('2024-01-14 04:22:21', 'YYYY-MM-DD HH24:MI:SS'), 'MANUAL', 'TRALIPL');
INSERT INTO EMF_PROCESS_MAPPING (MAPPING_NAME, DATA_COLUMN_NAME, DATA_TABLE_NAME, WHERE_CLAUSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PROCESS_CODE) VALUES ('INC_DT GT TEST_DT', NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM DUAL
 WHERE
    (SELECT incident_date 
       FROM health_history hh 
      WHERE hh.transaction_id = (SELECT A.transaction_id FROM DONATIONS A WHERE A.unit_id = :P_UNIT_ID)
        AND hh.question_code :P_OPER_QUESTION_CODE :P_VALUE_QUESTION_CODE
        AND hh.answer_code  :P_OPER_ANSWER_CODE :P_VALUE_ANSWER_CODE
        AND ROWNUM = 1
     ) > (SELECT NVL(MAX(UT.COLL_DATE), SYSDATE+400)
            FROM UTRS UT
           WHERE UNIT_ID IN (SELECT UNIT_ID
                               FROM DONATIONS
                              WHERE DONOR_ID = (SELECT DONOR_ID FROM DONATIONS WHERE UNIT_ID = :P_UNIT_ID)
                                AND UNIT_ID IS NOT NULL)
             AND UT.TEST_ID :P_OPER_TEST_ID :P_VALUE_TEST_ID
             AND UT.RESULT_STATUS_1 :P_OPER_RESULT_STATUS_1 :P_VALUE_RESULT_STATUS_1
             AND CANCEL_FLAG IS NULL
        )', 'VDIEMCFG', TO_DATE('2024-01-14 04:22:21', 'YYYY-MM-DD HH24:MI:SS'), 'MANUAL', 'TRALIPL');
