  FROM DUAL
 WHERE
    (SELECT incident_date 
       FROM health_history hh 
      WHERE hh.transaction_id = (SELECT A.transaction_id FROM DONATIONS A WHERE A.unit_id = :P_UNIT_ID)
        AND hh.question_code IN ( SELECT REGEXP_SUBSTR(''4.35,4.29-A'',''[^,]+'', 1, LEVEL) FROM DUAL
                  CONNECT BY REGEXP_SUBSTR(''4.35,4.29-A'', ''[^,]+'', 1, LEVEL) IS NOT NULL)
        AND hh.answer_code  = ''PREG1''
        AND ROWNUM = 1
     ) > (SELECT NVL(MAX(di.eff_date), SYSDATE - 100)
            FROM donor_interdictions di
            WHERE di.donor_id = ( SELECT dn.donor_id FROM donations dn WHERE dn.unit_id = :P_UNIT_ID)
                AND trunc(sysdate) BETWEEN di.eff_date AND nvl(di.term_date, sysdate + 10)
