INSERT INTO EMF_SOURCE_PROCESS (PROCESS_CODE, PROCESS_AT, PROCESS_SEQ, LOOKING_FOR, DATA_TABLE_NAME, DATA_COLUMN_NAME, SQL_OPER, RESPONSE, SQL_STMT, PROGRAM_ID, INSERT_DATE, INSERT_USER, PARAM_FLAG, SQL_OUT) VALUES ('TRALIPL', NULL, 7, 'INC_DT GT TEST_DT', NULL, NULL, NULL, NULL, 'SELECT COUNT(1)
  FROM DUAL
 WHERE
    (SELECT incident_date 
       FROM health_history hh 
      WHERE hh.transaction_id = (SELECT A.transaction_id FROM DONATIONS A WHERE A.unit_id = :P_UNIT_ID)
        AND hh.question_code IN ( SELECT REGEXP_SUBSTR(''4.35,4.29-A'',''[^,]+'', 1, LEVEL) FROM DUAL
                  CONNECT BY REGEXP_SUBSTR(''4.35,4.29-A'', ''[^,]+'', 1, LEVEL) IS NOT NULL)
        AND hh.answer_code  = ''PREG1''
        AND ROWNUM = 1
     ) > (SELECT NVL(MAX(UT.COLL_DATE), SYSDATE+400)
            FROM UTRS UT
           WHERE UNIT_ID IN (SELECT UNIT_ID
                               FROM DONATIONS
                              WHERE DONOR_ID = (SELECT DONOR_ID FROM DONATIONS WHERE UNIT_ID = :P_UNIT_ID)
                                AND UNIT_ID IS NOT NULL)
             AND UT.TEST_ID = ''HLA''
             AND UT.RESULT_STATUS_1 IN ( SELECT REGEXP_SUBSTR(''N'',''[^,]+'', 1, LEVEL) FROM DUAL
                  CONNECT BY REGEXP_SUBSTR(''N'', ''[^,]+'', 1, LEVEL) IS NOT NULL)
             AND CANCEL_FLAG IS NULL
        )', 'VEMFPROC', TO_DATE('2024-02-20 00:00:00', 'YYYY-MM-DD HH24:MI:SS'), 'SBCSYS', 'Y', NULL);
